INSERT INTO "chatbot_knowledge_base" ("id", "question", "answer", "keywords", "created_at") VALUES (48, 'Can I save my monthly report as a draft and finish it later?', 'Yes! You can click \''Save Draft\'' at any time while working on your Church or Zonal report. All entered numbers, expenses, and spiritual statistics are securely saved. When you return, you can continue right where you left off until you are ready for final submission.', 'draft, save draft, continue later, resume report, edit draft, unfinished report', '2026-08-29T13:20:36.533006') ON CONFLICT DO NOTHING;
